"use strict";(globalThis.webpackChunkpic_protocol=globalThis.webpackChunkpic_protocol||[]).push([[130],{7735(t){t.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"Welcome to PIC","metadata":{"permalink":"/blog/Welcome to PIC","source":"@site/blog/2025-12-22-welcome/index.md","title":"Welcome to PIC","description":"PIC (Provenance Identity Continuity) is a new authorization model that changes how we think about trust in distributed systems.","date":"2025-12-22T00:00:00.000Z","tags":[{"inline":true,"label":"pic","permalink":"/blog/tags/pic"},{"inline":true,"label":"authorization","permalink":"/blog/tags/authorization"},{"inline":true,"label":"security","permalink":"/blog/tags/security"},{"inline":true,"label":"ai-agents","permalink":"/blog/tags/ai-agents"}],"readingTime":1.15,"hasTruncateMarker":true,"authors":[{"name":"Nicola Gallo","title":"Software Architect, Creator of PIC, ZTAuth* and Permguard, Co-founder Nitro Agiltiy","url":"https://linkedin.com/in/nicolagallo","page":{"permalink":"/blog/authors/nicolagallo"},"socials":{"website":"https://www.nitroagility.com","x":"https://x.com/ngallo83","linkedin":"https://www.linkedin.com/in/nicolagallo83/","github":"https://github.com/ngallo","newsletter":"https://www.ngallo.it"},"imageURL":"https://github.com/ngallo.png","key":"nicolagallo"}],"frontMatter":{"slug":"Welcome to PIC","title":"Welcome to PIC","authors":["nicolagallo"],"tags":["pic","authorization","security","ai-agents"]},"unlisted":false},"content":"**PIC (Provenance Identity Continuity)** is a new authorization model that changes how we think about trust in distributed systems.\\n\\nFor 40 years, security has been built on Proof of Possession: \\"Do you have a valid token? Come in.\\"\\n\\nBut possession can be stolen. And trust doesn\'t survive multiple hops.\\n\\n\x3c!-- truncate --\x3e\\n\\n## The Problem\\n\\nToday\'s systems verify possession at each hop:\\n\\n- Service A has token. Ok.\\n- Service A calls Service B. Service B checks its own token. Ok.\\n\\nNobody asks:\\n\\n- Who started this?\\n- What were the original bounds?\\n- Is this a valid continuation?\\n\\nEach hop restarts. Origin lost. Chain broken.\\n\\nThis is why AI agents are breaking everything.\\n\\n## The Solution\\n\\nPIC flips the model.\\n\\nOld question: \\"Do you have a valid token?\\"\\n\\nNew question: \\"Can you prove you can continue this chain?\\"\\n\\nEvery action carries:\\n\\n- **Origin** \u2014 who started. Immutable.\\n- **Authority** \u2014 what\'s allowed. Can only shrink.\\n- **Continuity** \u2014 proof linking every action to the source.\\n\\n## Why It Matters\\n\\nYou tell an AI: \\"Book a flight, max \u20ac500.\\"\\n\\nAI calls booking. Booking calls payment. Payment calls bank.\\n\\nFifty hops. Doesn\'t matter.\\n\\nEvery hop: origin is you. Authority is \u20ac500.\\n\\nAI tries \u20ac5000? Rejected. Someone intercepts? Nothing to steal.\\n\\n## Get Started\\n\\n- Read the [PIC Specification](https://github.com/pic-protocol/pic-spec)\\n- Explore the [formal proofs](https://zenodo.org/records/17833000)\\n- Join the discussion\\n\\nNot \\"what do you have?\\" \u2014 but \\"can you prove you can continue?\\"\\n\\nThat\'s PIC."}]}}')}}]);